uted);margin-bottom:var(--space-7)}.art{height:var(--art-height);margin-bottom:var(--space-7);display:flex;justify-content:center}.art svg{width:100%;height:100%;overflow:visible}.steps{list-style:none;margin:var(--space-6) 0 var(--space-7);padding:0}.steps li{display:flex;align-items:center;gap:var(--space-4);padding:var(--space-3) 0;border-top:var(--border) solid var(--line)}.steps li:last-child{border-bottom:var(--border) solid var(--line)}.step-number{flex-shrink:0;display:grid;place-items:center;height:var(--space-8);width:var(--space-8);border:var(--border) solid var(--input-border);border-radius:var(--radius-circle);font-size:var(--fs-small)}.primary{width:100%;min-height:var(--target);display:flex;justify-content:center;align-items:center;gap:var(--space-3);padding:var(--space-3) var(--space-5);border:var(--border-strong) solid transparent;border-radius:var(--radius-button);background:var(--primary);color:var(--on-primary);font-weight:var(--weight-bold);text-decoration:none;transition:opacity var(--duration) var(--ease)}.primary:hover{opacity:0.9}.primary svg{height:var(--space-5);width:var(--space-5)}.next-note{color:var(--muted);font-size:var(--fs-small);margin-top:var(--space-4)}.footer{padding:var(--space-4) var(--space-6) var(--space-6);font-size:var(--fs-tiny);color:var(--muted);line-height:var(--leading)}.eyebrow{font-size:var(--fs-small);color:var(--muted);margin-bottom:var(--space-4);display:flex;align-items:center;gap:var(--space-3)}.progress{display:flex;gap:var(--space-1)}.progress i{width:var(--space-5);height:var(--space-1);background:var(--line)}.progress i.active{background:var(--fg)}.field{margin-bottom:var(--space-6)}label{display:block;font-weight:var(--weight-bold);margin-bottom:var(--space-2)}.hint{font-size:var(--fs-small);color:var(--muted);margin:var(--space-2) 0 0}input{display:block;width:100%;min-height:var(--target);padding:var(--space-3) var(--space-4);background:var(--surface);border:var(--border) solid var(--input-border);border-radius:var(--radius-input);color:var(--fg);caret-color:var(--fg)}input[aria-invalid=\"true\"]{border:var(--border-strong) solid var(--error)}.error{font-size:var(--fs-small);color:var(--error);margin-top:var(--space-2);font-weight:var(--weight-medium)}.error-summary{padding:var(--space-3) var(--space-4);border-left:var(--border-strong) solid var(--error);background:var(--error-bg);margin-bottom:var(--space-6);font-size:var(--fs-small);color:var(--error)}.before-action{margin:var(--space-2) 0 var(--space-6);color:var(--muted);font-size:var(--fs-small)}.code-input{font-size:var(--fs-code);letter-spacing:var(--tracking-code);font-variant-numeric:tabular-nums;font-weight:var(--weight-medium)}.safety{display:flex;gap:var(--space-3);align-items:flex-start;background:var(--warning);border-radius:var(--radius-panel);padding:var(--space-4);margin:var(--space-6) 0;color:var(--fg);font-size:var(--fs-small)}.safety svg{width:var(--space-6);height:var(--space-6);flex-shrink:0;margin-top:var(--space-1)}.safety strong{display:block;margin-bottom:var(--space-1);font-weight:var(--weight-bold)}.change-number{margin-top:var(--space-4);display:block;width:100%;text-decoration:underline;text-underline-offset:var(--space-1)}.prototype-note{font-size:var(--fs-small);color:var(--muted);margin:var(--space-4) 0}.success-mark{display:grid;place-items:center;width:var(--target);height:var(--target);background:var(--success-bg);color:var(--success);border-radius:var(--radius-circle);margin-bottom:var(--space-6)}.success-mark svg{width:var(--space-8);height:var(--space-8)}.account{background:var(--surface);border:var(--border) solid var(--line);border-radius:var(--radius-panel);padding:var(--space-5);margin:var(--space-7) 0}.account-label{font-size:var(--fs-small);color:var(--muted);margin:var(--space-5) 0 var(--space-1)}.balance{font-family:var(--font-heading);font-size:var(--fs-balance)}dl{margin:var(--space-5) 0 0;padding-top:var(--space-4);border-top:var(--border) solid var(--line);font-size:var(--fs-small)}dl div{display:flex;justify-content:space-between;gap:var(--space-3);margin-top:var(--space-2)}dt{color:var(--muted)}dd{margin:0;font-variant-numeric:tabular-nums}details{margin-top:var(--space-6);font-size:var(--fs-small)}summary{cursor:pointer;min-height:var(--target-small);padding:var(--space-3) 0;text-decoration:underline;text-underline-offset:var(--space-1)}dialog{width:calc(100% - var(--space-8));max-width:var(--dialog-width);max-height:calc(100svh - var(--space-8));padding:var(--space-7);border:var(--border) solid var(--line);border-radius:var(--radius-dialog);background:var(--bg);color:var(--fg);box-shadow:var(--shadow-dialog);overflow-y:auto}dialog::backdrop{background:var(--overlay)}dialog h2{font-family:var(--font-heading);font-size:var(--fs-balance);font-weight:var(--weight-normal);line-height:var(--leading-title);margin-bottom:var(--space-4)}dialog p{color:var(--muted);margin-bottom:var(--space-5)}.phone-link{display:flex;align-items:center;justify-content:center;gap:var(--space-2);min-height:var(--target);padding:var(--space-3) var(--space-2);color:var(--fg);border:var(--border) solid var(--input-border);border-radius:var(--radius-button);font-size:var(--fs-lead);font-weight:var(--weight-bold);text-decoration:none;margin:var(--space-5) 0}.phone-link svg{height:var(--space-6);width:var(--space-6);flex-shrink:0}.help-small{font-size:var(--fs-small)}.sr-only{position:absolute;width:1px;height:1px;margin:-1px;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
@media(max-width:350px){.header{padding:var(--space-4) var(--space-5)}main{padding-left:var(--space-5);padding-right:var(--space-5)}.art{height:var(--space-12);margin-bottom:var(--space-6)}.welcome .art{height:var(--art-height)}dialog{padding:var(--space-5)}.phone-link{font-size:var(--fs-body)}}
@media(min-width:600px){#app{border-left:var(--border) solid var(--line);border-right:var(--border) solid var(--line)}}
@media(prefers-reduced-motion:reduce){*,*::before,*::after{transition:none"'!important;animation:none!important;scroll-behavior:auto!important}}
